patches.old:
if let d = v.stages.first(where: { !$0.identical }) {
    return (true, "ESTABLISHED by the " + name + " trace (both trace finals equal their uninstrumented "
            + "originals): first divergence at stage " + d.stage + " index " + String(d.firstIndex ?? -1)
            + " (" + (d.locator ?? "") + "), production " + (d.productionHex ?? "?") + " register "
            + (d.registerHex ?? "?") + "; decode operands identical")
}

patches.new:
if let d = v.stages.first(where: { !$0.identical }) {
    let indexText: String = String(d.firstIndex ?? -1)
    let locatorText: String = d.locator ?? ""
    let productionText: String = d.productionHex ?? "?"
    let registerText: String = d.registerHex ?? "?"
    var s: String = "ESTABLISHED by the " + name
    s += " trace (both trace finals equal their uninstrumented originals): first divergence at stage "
    s += d.stage
    s += " index " + indexText
    s += " (" + locatorText + "), production " + productionText
    s += " register " + registerText + "; decode operands identical"
    return (true, s)
}
